summary:
bash: cat > /tmp/test_klee.c << 'EOF'
#include <klee/klee.h>
#include <stdio.h>

int main() {
    int x;
    klee_make_symbolic(&x, sizeof(x), "x");
    if (x > 0) {
        printf("x is positive\n");
    } else {
        printf("x is non-positive\n");
    }
    return 0;
}
EOF
clang-16 -I/usr/local/include/klee -c /tmp/test_klee.c -o /tmp/test_klee.bc 2>&1 && klee /tmp/test_klee.bc 2>&1 | head -15

